-- Results of a Chrome-assisted verification pass (docs/browser-prompts/01), 2026-10-28. Each owner below says American mahjong / NMJL on its own page; the quote is stored in the description.
UPDATE "Club" SET "status" = 'ACTIVE', "lastVerifiedAt" = '2026-10-28', "description" = 'Riverchase United Methodist Church''s own event page says: "You will learn how to play this fun game of strategy, skill, and luck using the American National Mahjongg League (NMJL) rules." Free lessons on the first Thursday of the month, 1-3 PM, in Room 111; open play follows for those who have had the first lesson.', "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'birmingham-riverchase-united-methodist-church-mah-jongg-lessons' AND "status" = 'NEEDS_REVIEW';
UPDATE "Club" SET "status" = 'ACTIVE', "lastVerifiedAt" = '2026-10-28', "description" = 'Aldridge Gardens'' own Mah Jongg page says: "Mah Jongg Open Play is free and open to anyone who knows how to play American Mah Jongg." Open play and beginner lessons on the first and third Sundays at the garden in Hoover (lessons need a reservation; open play does not).', "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'birmingham-aldridge-gardens-mahjong-classes-open-play-cynde-morgan' AND "status" = 'NEEDS_REVIEW';
UPDATE "Club" SET "status" = 'ACTIVE', "lastVerifiedAt" = '2026-10-28', "description" = 'The City of Waukesha''s online registration lists an "American Mah Jongg Class" (18+) and "American Mah Jongg Meet Ups" (55+) at the Schuetze Recreation Center. Register through the city''s Active Communities site; start times are shown at registration.', "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'milwaukee-city-of-waukesha-55-american-mahjong-class-meet-ups-schuetze-rec-center' AND "status" = 'NEEDS_REVIEW';
UPDATE "Instructor" SET "status" = 'ACTIVE', "lastVerifiedAt" = '2026-10-28', "notes" = 'Runs the Birmingham Mahjong League; its own clubs and leagues page says "NMJL Rules Only". Leagues are sign-up based, three seasons a year.', "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'birmingham-all-about-mahj-bham-kandb-mahj' AND "status" = 'NEEDS_REVIEW';
UPDATE "Instructor" SET "status" = 'ACTIVE', "lastVerifiedAt" = '2026-10-28', "notes" = 'Facebook page says: "American Mahjong instruction. Experienced large event Director for Tournaments/Social/Fundraising Mahjong events in Bhm or Lake Martin, AL". Private lessons for 4-12 players of all levels.', "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'birmingham-tapping-mahjette-tapping-mahjette-llc-the-tapping-mahjette-omm-teacher-the-tapping-mahjette' AND "status" = 'NEEDS_REVIEW';
